debug_text.text:
'ProtectSector [%s at %s, %s]: SubordinatesRefresh: refreshing the Subordinates group.'.
            [
              @this.assignedcontrolled.debugname,
              @this.assignedcontrolled.sector.knownname,
              @this.assignedcontrolled.fleet.name
            ]

find_object.sortbyvalue:
(if loop.element.pilot.$targetedBy? and @loop.element.pilot.$targetedBy != this.assignedcontrolled.idcode and @loop.element.pilot.$ignoreTime gt player.age then 1000km else 0km) +
                  (if @loop.element.relationto.{this.owner} le $relationsThresholdInternal then 0km else 1000km) +
                  (if $macrosToSkip.indexof.{@loop.element.macro} == 0 then 0km else 1000km) + loop.element.distanceto.{this.assignedcontrolled}

(if loop.element.pilot.$targetedBy? and @loop.element.pilot.$targetedBy != this.assignedcontrolled.idcode and @loop.element.pilot.$ignoreTime gt player.age then 1000km else 0km) +
                  (if @loop.element.relationto.{this.owner} le $relationsThresholdInternal then 0km else 1000km) +
                  (if $macrosToSkip.indexof.{@loop.element.macro} == 0 then 0km else 1000km) + loop.element.distanceto.{this.assignedcontrolled}

(if loop.element.pilot.$targetedBy? and @loop.element.pilot.$targetedBy != this.assignedcontrolled.idcode and @loop.element.pilot.$ignoreTime gt player.age then 1000km else 0km) +
                  (if @loop.element.relationto.{this.owner} le $relationsThresholdInternal then 0km else 1000km) +
                  (if $macrosToSkip.indexof.{@loop.element.macro} == 0 then 0km else 1000km) + loop.element.distanceto.{this.assignedcontrolled}

(if loop.element.pilot.$targetedBy? and @loop.element.pilot.$targetedBy != this.assignedcontrolled.idcode and @loop.element.pilot.$ignoreTime gt player.age then 1000km else 0km) +
                  (if @loop.element.relationto.{this.owner} le $relationsThresholdInternal then 0km else 1000km) +
                  (if $macrosToSkip.indexof.{@loop.element.macro} == 0 then 0km else 1000km) + loop.element.distanceto.{this.assignedcontrolled}

debug_text.text:
'ProtectSector [%s at %s, %s]: Event: %s, our : %s {%s} in sector: %s with order: %s, top commander:  %s {%s} in sector: %s with order: %s,  assigned:  %s {%s} in sector: %s with order: %s, assigned top commander:  %s {%s} in sector: %s with order: %s, attacker: %s {%s}'
            .[
              this.assignedcontrolled.debugname,
              this.assignedcontrolled.sector.knownname,
              this.assignedcontrolled.fleet.name,
              @event.name,
              @event.object.debugname,
              @event.object.class,
              @event.object.sector.knownname,
              @event.object.defaultorder.id,
              @event.object.toplevelcommander.debugname,
              @event.object.toplevelcommander.class,
              @event.object.toplevelcommander.sector.knownname,
              @event.object.toplevelcommander.defaultorder.id,
              @event.object.assignedcontrolled.debugname,
              @event.object.assignedcontrolled.class,
              @event.object.assignedcontrolled.sector.knownname,
              @event.object.assignedcontrolled.defaultorder.id,
              @event.object.assignedcontrolled.toplevelcommander.debugname,
              @event.object.assignedcontrolled.toplevelcommander.class,
              @event.object.assignedcontrolled.toplevelcommander.sector.knownname,
              @event.object.assignedcontrolled.toplevelcommander.defaultorder.id,
              @event.param.debugname,
              @event.param.class
            ]

'ProtectSector [%s at %s, %s]: Event: %s : %s{%s} status: iswreck: %s, isoperational: %s,  pilot: %s (%s), param: %s {%s}, target info - %s'
            .[
              this.assignedcontrolled.debugname,
              this.assignedcontrolled.sector.knownname,
              this.assignedcontrolled.fleet.name,
              @event.name,
              @event.object.debugname,
              @event.object.class,
              @event.object.iswreck,
              @event.object.isoperational,
              @event.object.pilot,
              event.object.pilot?,
              @event.param.debugname,
              @event.param.class,
              @$targetInfo
            ]

'ProtectSector [%s at %s, %s]: SubordinateLostHandler: requesting fleet replacements for %s units.'.
            [
              @this.assignedcontrolled.debugname,
              @this.assignedcontrolled.sector.knownname,
              @this.assignedcontrolled.fleet.name,
              @this.assignedcontrolled.fleetunits.count
            ]

'ProtectSector [%s at %s, %s]: ReScan result. Target found: %s. Relation: %s. Threshold: %s. Distance: %s. Idle till: %s'.
            [
              @this.assignedcontrolled.debugname,
              @this.assignedcontrolled.sector.knownname,
              @this.assignedcontrolled.fleet.name,
              @$ships.{1}.debugname,
              @$ships.{1}.relationto.{this.owner},
              $relationsThresholdInternal,
              @$ships.{1}.distanceto.{this.assignedcontrolled},
              $idleTill
            ]

'ProtectSector [%s at %s, %s]: ReScan stations result. Target found: %s. Relation: %s. Threshold: %s. Distance: %s.'.
                  [
                    @this.assignedcontrolled.debugname,
                    @this.assignedcontrolled.sector.knownname,
                    @this.assignedcontrolled.fleet.name,
                    @$reScanStationPick.debugname,
                    @$reScanStationPick.relationto.{this.owner},
                    $relationsThresholdInternal,
                    @$reScanStationPick.distanceto.{this.assignedcontrolled}
                  ]

'ProtectSector [%s at %s, %s]: target %s {%s} lost or out of engage range while attacking (cansee: %s, distance: %s, limit: %s). Breaking off. Pursue fleeing target: %s.'.
            [
              @this.assignedcontrolled.debugname,
              @this.assignedcontrolled.sector.knownname,
              @this.assignedcontrolled.fleet.name,
              @$target.debugname,
              @$target.class,
              this.assignedcontrolled.cansee.{$target},
              this.assignedcontrolled.distanceto.{$target},
              $targetOptimalDistanceForAttack,
              $pursueFleeingTarget
            ]

'ProtectSector [%s at %s, %s]: CheckSubordinatesAttack: Checking subordinates (count) %s in escort group (count) %s for attack orders and targets.'.
            [
              @this.assignedcontrolled.debugname,
              @this.assignedcontrolled.sector.knownname,
              @this.assignedcontrolled.fleet.name,
              @this.assignedcontrolled.subordinates.count,
              @this.$escortgroup.count
            ]

'ProtectSector [%s at %s, %s]: CheckSubordinatesAttack: New signal scheduled in %s.'.
              [
                @this.assignedcontrolled.debugname,
                @this.assignedcontrolled.sector.knownname,
                @this.assignedcontrolled.fleet.name,
                $signalDelay
              ]

'ProtectSector [%s at %s, %s]: Stopping to work. Going to set order %s (%s) failed with message: %s'.[
            this.assignedcontrolled.debugname,
            this.assignedcontrolled.sector.knownname,
            this.assignedcontrolled.fleet.name,
            @this.assignedcontrolled.order.id,
            @this.assignedcontrolled.defaultorder.id,
            $stoppingToWorkMessage
          ]

'ProtectSector [%s at %s, %s]: Aborting order due to %s, object: %s, param: %s, exists: %s, isoperational: %s, iswreck: %s, hull: %s'.[
        @this.assignedcontrolled.debugname,
        @this.assignedcontrolled.sector.knownname,
        @this.assignedcontrolled.fleet.name,
        @event.name,
        @event.object,
        @event.param,
        @this.assignedcontrolled.exists,
        @this.assignedcontrolled.isoperational,
        @this.assignedcontrolled.iswreck,
        @this.assignedcontrolled.hullpercentage
      ]

'ProtectSector [%s at %s, %s]: Aborting order. Order: %s, Default order: %s. Orders: %s, count: %s. Next order: %s.'.
      [
        @this.assignedcontrolled.debugname,
        @this.assignedcontrolled.sector.knownname,
        @this.assignedcontrolled.fleet.name,
        @this.assignedcontrolled.order.id,
        @this.assignedcontrolled.defaultorder.id,
        @this.assignedcontrolled.orders,
        @this.assignedcontrolled.orders.count,
        @this.assignedcontrolled.nextorder
      ]
